18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export type Step =
23	  | { op: "quote"; items: Item[] }
24	  | { op: "claim"; policy: number; incident: Incident };
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type StepResult =
32	  | { premium: number }
33	  | { payout: number; remainingCap: number };
34	
35	export interface ScenarioResult {
36	  results: StepResult[];
37	}
38	
39	const PROCESSING_FEE = 5;
40	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
41	
42	const percentOf = (amount: number, percent: number): number =>
43	  (amount * percent) / 100;
44	
45	const BASE_PREMIUM_BY_ITEM_TYPE = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	  moonstone: 25,
52	} as const satisfies Record<string, number>;
53	
54	type InsurableItemType = keyof typeof BASE_PREMIUM_BY_ITEM_TYPE;
55	
56	const COMPONENT_BLOCK_SIZE = 3;
57	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
58	
59	const basePremiumOf = (item: Item): number =>
60	  BASE_PREMIUM_BY_ITEM_TYPE[item.type as InsurableItemType];
61	
62	const isComponentBlock = (items: Item[]): boolean =>
63	  items.length === COMPONENT_BLOCK_SIZE &&
64	  items.every((item) => item.type === items[0].type);
65	
66	const policyBasePremium = (items: Item[]): number => {
67	  if (isComponentBlock(items)) return COMPONENT_BLOCK_BASE_PREMIUM;
68	  return items.reduce((sum, item) => sum + basePremiumOf(item), 0);
69	};
70	
71	const quotePremium = (items: Item[]): number => {
72	  const policyBase = policyBasePremium(items);
73	  const premiumBeforeFee =
74	    policyBase + percentOf(policyBase, FIRST_INSURANCE_SURCHARGE_PERCENT);
75	  return Math.ceil(premiumBeforeFee + PROCESSING_FEE);
76	};
77	
78	const runStep = (step: Step): StepResult => {
79	  if (step.op === "quote") return { premium: quotePremium(step.items) };
80	  throw new Error("claim steps are not implemented yet");
81	};
82	
83	export const runScenario = (scenario: Scenario): ScenarioResult => ({
84	  results: scenario.steps.map(runStep),
85	});
